 public static class Polish {
  public static bool Review(IWin32Window owner,string title,string beforeAfter){using(var f=new NextDialog(title,850,600)){f.Body.Controls.Add(new TextBox{Multiline=true,ReadOnly=true,ScrollBars=ScrollBars.Both,Dock=DockStyle.Fill,Text=beforeAfter,WordWrap=false,AccessibleName="Changes to review"});f.Action("Apply reviewed changes",()=>f.DialogResult=DialogResult.OK);f.Action("Cancel",()=>f.DialogResult=DialogResult.Cancel);return f.ShowDialog(owner)==DialogResult.OK;}}
  public static string ImportSummary(LibraryData current,LibraryData incoming){return "Replace these FishBowl settings. Game and save files themselves will not be moved.\r\nA restore point will be created before replacement.\r\n\r\n"+"Games: "+current.Games.Count+" → "+(incoming.Games??new List<GameEntry>()).Count+"\r\nEmulators: "+current.Emulators.Count+" → "+incoming.Emulators.Count+"\r\nUser profiles: "+UserTools.Ensure(current).Users.Count+" → "+(incoming.UserTools==null||incoming.UserTools.Users==null?1:incoming.UserTools.Users.Count)+"\r\nTheme: "+(current.Theme==null?"Default":current.Theme.Name)+" → "+(incoming.Theme==null?"Default":incoming.Theme.Name)+"\r\n\r\nIncoming games (first 100):\r\n"+string.Join("\r\n",(incoming.Games??new List<GameEntry>()).Take(100).Select(g=>g.Title+" | "+g.Path));}
  public static string BulkSummary(IEnumerable<GameEntry> games,string emulator,string status,string favorite,string pinned,string tags,string art,string collection){var b=new StringBuilder("Only the following fields will change. Other fields and game/save files stay unchanged.\r\n\r\n");foreach(var g in games){b.AppendLine(g.Title);if(emulator!="Keep current")b.AppendLine("  Emulator assignment → "+emulator);if(status!="Keep current")b.AppendLine("  Status: "+g.PlayStatus+" → "+status);if(favorite!="Keep current")b.AppendLine("  Favorite: "+g.Favorite+" → "+(favorite=="Favorite"));if(pinned!="Keep current")b.AppendLine("  Pinned: "+g.Pinned+" → "+(pinned=="Pin"));if(!string.IsNullOrWhiteSpace(tags))b.AppendLine("  Tags: "+string.Join(", ",g.Tags??new List<string>())+" → add "+tags);if(!string.IsNullOrWhiteSpace(art))b.AppendLine("  Artwork: "+g.ArtworkPath+" → "+art);if(collection!="None")b.AppendLine("  Collection → add to "+collection);b.AppendLine();}return b.ToString();}
  public static List<HealthIssue> Health(LibraryData d,CancellationToken token){var issues=new List<HealthIssue>();foreach(var g in d.Games){token.ThrowIfCancellationRequested();if(!File.Exists(NextData.LaunchPath(g)))issues.Add(new HealthIssue{Area="Game file",GameId=g.Id,Message=g.Title+": missing file. Choose a replacement in Repair game paths."});var e=ExperienceData.Emulator(d,g);if(!Hub.Native(g)&&(e==null||!File.Exists(NextData.LaunchEmulator(d,g).Executable)))issues.Add(new HealthIssue{Area="Emulator",GameId=g.Id,Message=g.Title+": assign an available emulator in game settings."});if(string.IsNullOrWhiteSpace(g.ArtworkPath)||!File.Exists(g.ArtworkPath))issues.Add(new HealthIssue{Area="Artwork",GameId=g.Id,Message=g.Title+": artwork unavailable. Choose a local image in game settings."});foreach(var save in g.Saves??new List<GameSaveEntry>())if(!File.Exists(save.Path)&&!Directory.Exists(save.Path))issues.Add(new HealthIssue{Area="Linked save",GameId=g.Id,Message=g.Title+": linked save unavailable; review its save associations."});}foreach(var s in d.SaveSnapshots??new List<SaveSnapshot>()){token.ThrowIfCancellationRequested();if(!File.Exists(s.Path)&&!Directory.Exists(s.Path))issues.Add(new HealthIssue{Area="Backup",GameId=s.GameId,Message="Missing save snapshot: "+s.Path});}if(!string.IsNullOrWhiteSpace(d.BackupFolder)&&!Directory.Exists(d.BackupFolder))issues.Add(new HealthIssue{Area="Backup",Message="Configured backup folder is unavailable: "+d.BackupFolder});return issues;}
  public static void HealthScreen(IWin32Window owner,LibraryData d){var issues=BackgroundWork<List<HealthIssue>>.Run(owner,"Check Library health",(token,progress)=>{progress("Checking configured files and folders…");return Health(d,token);});if(issues==null)return;using(var f=new NextDialog("Library health")){var list=new ListView{Dock=DockStyle.Fill,View=View.Details,FullRowSelect=true,HideSelection=false,AccessibleName="Library health issues"};list.Columns.Add("Area",120);list.Columns.Add("Issue and next step",660);foreach(var issue in issues)list.Items.Add(new ListViewItem(new[]{issue.Area,issue.Message}){Tag=issue});if(issues.Count==0)list.Items.Add(new ListViewItem(new[]{"Ready","No missing configured files detected. Emulator compatibility still needs a game test."}));f.Body.Controls.Add(list);f.Action("Resolve selected game",()=>{if(list.SelectedItems.Count==0)return;var issue=list.SelectedItems[0].Tag as HealthIssue;var g=issue==null?null:d.Games.FirstOrDefault(x=>x.Id==issue.GameId);if(g!=null)UserTools.Troubleshoot(f,d,g,null);else UserTools.Report(f,"Backup issue","Use Backup verification and retention to select a known archive. Reconnect missing backup drives before restoring.");});f.Action("Verify save snapshots",()=>{var result=BackgroundWork<string>.Run(f,"Verify snapshot contents",(token,progress)=>{var b=new StringBuilder();foreach(var snapshot in d.SaveSnapshots??new List<SaveSnapshot>()){token.ThrowIfCancellationRequested();progress(snapshot.Path);try{SaveHistory.Verify(snapshot,token);b.AppendLine("Verified: "+snapshot.Path);}catch(OperationCanceledException){throw;}catch(Exception ex){b.AppendLine("Issue: "+snapshot.Path+" — "+ex.Message);}}return b.Length==0?"No save snapshots yet. Create a snapshot from Saves and history first.":b.ToString();});if(result!=null)UserTools.Report(f,"Snapshot verification",result);});f.Action("Repair game paths",()=>ExperienceTools.Relink(f,d));f.Action("Close",f.Close);f.ShowDialog(owner);}}
  public static string DeviceReport(LibraryData d){var b=new StringBuilder("Connected XInput controller: "+(UserToolRuntime.ControllerConnected()?"detected":"none detected")+"\r\n\r\nEmulator installations:\r\n");foreach(var e in d.Emulators){try{b.AppendLine(e.Name+": "+(File.Exists(e.Executable)?FileVersionInfo.GetVersionInfo(e.Executable).FileVersion:"executable missing"));}catch(Exception ex){b.AppendLine(e.Name+": "+ex.Message);}}b.AppendLine("\r\nFor a real game check: use a copy of a game you own, select an isolated save route where supported, launch, verify controller navigation, close the emulator, then check the session journal. Break reminders depend on Windows notification settings. This inventory does not claim game compatibility.");return b.ToString();}
  public static void Accessibility(Control root){var fields=root as TableLayoutPanel;if(fields!=null){for(int row=0;row<fields.RowStyles.Count;row++){if(fields.RowStyles[row].SizeType!=SizeType.Absolute||fields.RowStyles[row].Height==0)continue;int height=(int)fields.RowStyles[row].Height;for(int column=0;column<fields.ColumnCount;column++){var control=fields.GetControlFromPosition(column,row);if(control==null)continue;height=Math.Max(height,control.Font.Height+24);if(control is Label)height=Math.Max(height,TextRenderer.MeasureText(control.Text,control.Font,new Size(Math.Max(100,control.Width),1000),TextFormatFlags.WordBreak).Height+16);if(control is FlowLayoutPanel)height=Math.Max(height,control.GetPreferredSize(new Size(Math.Max(100,control.Width),0)).Height+16);}fields.RowStyles[row].Height=height;}var panel=fields.Parent as Panel;if(panel!=null)panel.AutoScroll=true;}int index=0;foreach(Control c in root.Controls){c.TabIndex=index++;if(string.IsNullOrWhiteSpace(c.AccessibleName)){if(c is Button||c is CheckBox||c is Label||c is TabPage)c.AccessibleName=c.Text.Replace("&","");else if(c is ComboBox)c.AccessibleName="Choose an option";else if(c is ListView||c is ListBox)c.AccessibleName="Items";}if(c is Button){c.AccessibleRole=AccessibleRole.PushButton;if(c.Parent is FlowLayoutPanel){var action=c as FishBowlActionButton;if(action==null||!action.IconOnly)c.Width=Math.Max(c.Width,TextRenderer.MeasureText(c.Text,c.Font).Width+56);c.Height=Math.Max(c.Height,c.Font.Height+16);}}if(c is TextBoxBase&&((TextBoxBase)c).ReadOnly)c.TabStop=true;Accessibility(c);}if(fields!=null)for(int row=0;row<fields.RowStyles.Count;row++){if(fields.RowStyles[row].SizeType!=SizeType.Absolute||fields.RowStyles[row].Height==0)continue;for(int column=0;column<fields.ColumnCount;column++){var flow=fields.GetControlFromPosition(column,row) as FlowLayoutPanel;if(flow!=null)fields.RowStyles[row].Height=Math.Max(fields.RowStyles[row].Height,flow.GetPreferredSize(new Size(Math.Max(100,flow.Width),0)).Height+16);}}var toolbar=root as FlowLayoutPanel;if(toolbar!=null&&toolbar.Name=="FishBowlToolbar")toolbar.Height=Math.Max(48,toolbar.Controls.OfType<Button>().Select(b=>b.Height+b.Margin.Vertical+toolbar.Padding.Vertical).DefaultIfEmpty(48).Max());root.AccessibleDescription=string.IsNullOrWhiteSpace(root.AccessibleDescription)?"Use Tab and Shift+Tab to move between controls. Enter activates the focused command.":root.AccessibleDescription;}
 }
 public static class UserSaveRoutes {
  static string Identity(string value){using(var sha=SHA256.Create())return BitConverter.ToString(sha.ComputeHash(Encoding.UTF8.GetBytes(value??""))).Replace("-","").Substring(0,32);}
  public static string Root(LibraryData d,EmulatorProfile emulator){return Path.Combine(Store.DataDirectory,"UserEmulatorData",Identity(UserTools.Ensure(d).ActiveId),Identity(emulator.Id));}
  public static SaveRouting Route(LibraryData d,EmulatorProfile emulator){return (UserTools.Ensure(d).SaveRoutes??new List<SaveRouting>()).FirstOrDefault(r=>r.EmulatorId==emulator.Id);}
  public static string Arguments(LibraryData d,EmulatorProfile e,bool create){var r=Route(d,e);if(r==null||r.Mode=="Off"||string.IsNullOrWhiteSpace(r.Mode))return "";string root=Root(d,e);string saves=Path.Combine(root,"Saves"),states=Path.Combine(root,"States"),user=Path.Combine(root,"User");string result;
   if(r.Mode=="Dolphin user directory"){if(!Path.GetFileNameWithoutExtension(e.Executable).Equals("Dolphin",StringComparison.OrdinalIgnoreCase))throw new IOException("Dolphin save routing requires Dolphin.exe. Review this emulator's route.");result="--user "+Quote(user);if(create)Directory.CreateDirectory(user);}
   else if(r.Mode=="RetroArch save folders"){if(!Path.GetFileNameWithoutExtension(e.Executable).StartsWith("retroarch",StringComparison.OrdinalIgnoreCase))throw new IOException("RetroArch save routing requires a RetroArch executable.");string config=Path.Combine(root,"FishBowl-saves.cfg");result="--appendconfig "+Quote(config);if(create){Directory.CreateDirectory(saves);Directory.CreateDirectory(states);File.WriteAllText(config,"savefile_directory = "+Quote(saves.Replace('\\','/'))+"\n"+"savestate_directory = "+Quote(states.Replace('\\','/'))+"\nconfig_save_on_exit = false\n",new UTF8Encoding(false));}}
   else if(r.Mode=="Custom arguments"){if(string.IsNullOrWhiteSpace(r.Arguments)||!(r.Arguments.Contains("{saves}")||r.Arguments.Contains("{states}")||r.Arguments.Contains("{user}")))throw new IOException("Custom routing must use {saves}, {states} or {user}, without extra quotes around the token.");result=r.Arguments.Replace("{saves}",Quote(saves)).Replace("{states}",Quote(states)).Replace("{user}",Quote(user));if(result.Contains("{")||result.Contains("}"))throw new IOException("Unknown save-routing token.");if(create){Directory.CreateDirectory(saves);Directory.CreateDirectory(states);Directory.CreateDirectory(user);}}
   else throw new IOException("Unknown save-routing mode.");return result;
  }
  static string Quote(string path){if(path.Contains("\"")||path.Contains("\r")||path.Contains("\n"))throw new IOException("Invalid save path.");return "\""+path+"\"";}
  public static string Apply(LibraryData d,EmulatorProfile e,string args,bool create){string routing=Arguments(d,e,false);if(string.IsNullOrEmpty(routing))return args;var r=Route(d,e);string[] switches=r.Mode=="Dolphin user directory"?new[]{"--user","-u"}:r.Mode=="RetroArch save folders"?new[]{"--appendconfig","--save","--savestate","-s","-S"}:new string[0];if(switches.Any(flag=>System.Text.RegularExpressions.Regex.IsMatch(args??"","(^|\\s)"+System.Text.RegularExpressions.Regex.Escape(flag)+"(\\s|=|$)")))throw new IOException("Existing arguments already choose a user/save configuration. Remove that override or disable per-user routing to avoid conflicting locations.");return (args+" "+Arguments(d,e,create)).Trim();}
  public static void Show(IWin32Window owner,LibraryData d){if(UserTools.Guest)return;using(var f=new NextDialog("Per-user emulator saves")){var fields=NextDialog.Fields(f.Body);var choice=new ComboBox{DropDownStyle=ComboBoxStyle.DropDownList,DisplayMember="Name"};choice.Items.AddRange(d.Emulators.Cast<object>().ToArray());var mode=NextDialog.Choice(new[]{"Off","Dolphin user directory","RetroArch save folders","Custom arguments"},"Off");var args=new TextBox();var location=new TextBox{ReadOnly=true};NextDialog.Field(fields,"Emulator",choice);NextDialog.Field(fields,"Routing",mode);NextDialog.Field(fields,"Custom arguments",args,70);NextDialog.Field(fields,"Current user's managed folder",location,70);NextDialog.Field(fields,"Scope",new Label{Text="Off is the default. Dolphin isolates its entire user directory, including settings and Wii data. RetroArch routes save files and states. Custom flags require emulator support. Existing saves are never moved or copied automatically; a new route starts empty. Overrides inside the emulator can still affect save locations.",AutoSize=true},180);
   choice.SelectedIndexChanged+=(a,b)=>{var e=choice.SelectedItem as EmulatorProfile;if(e==null)return;var r=Route(d,e);mode.SelectedItem=r==null?"Off":r.Mode;args.Text=r==null?"":r.Arguments;location.Text=Root(d,e);};if(choice.Items.Count>0)choice.SelectedIndex=0;
   f.Action("Preview and save",()=>{var e=choice.SelectedItem as EmulatorProfile;if(e==null)throw new IOException("Add an emulator first.");if(UserTools.ActiveLaunches>0)throw new IOException("Close emulator sessions before changing save routing.");var s=UserTools.Ensure(d);var proposed=new SaveRouting{EmulatorId=e.Id,Mode=mode.Text,Arguments=args.Text};var clone=UserTools.Copy(d);var routes=UserTools.Ensure(clone).SaveRoutes??new List<SaveRouting>();routes.RemoveAll(r=>r.EmulatorId==e.Id);routes.Add(proposed);clone.UserTools.SaveRoutes=routes;string preview=Arguments(clone,e,false);if(!Polish.Review(f,"Review per-user save routing","Emulator: "+e.Name+"\r\nUser: "+s.Users.First(u=>u.Id==s.ActiveId).Name+"\r\nOld route: "+(Route(d,e)==null?"Off":Route(d,e).Mode)+"\r\nNew route: "+proposed.Mode+"\r\nManaged folder: "+Root(d,e)+"\r\nAdded launch arguments: "+preview+"\r\n\r\nNo original saves or configurations will be moved or overwritten. New folders are created on launch. Dolphin's new user folder needs its own setup."))return;if(s.SaveRoutes==null)s.SaveRoutes=new List<SaveRouting>();s.SaveRoutes.RemoveAll(r=>r.EmulatorId==e.Id);s.SaveRoutes.Add(proposed);Store.Save(d);f.Close();});f.Action("Close",f.Close);f.ShowDialog(owner);}}
 }
 public partial class GameLibraryDialog {
