  void FitLibraryHeader(){if(fittingHeader||search.Parent==null)return;var header=search.Parent as Panel;if(header==null)return;fittingHeader=true;try{var labels=header.Controls.OfType<Label>().OrderBy(l=>l.Top).ToList();var filters=header.Controls.OfType<FlowLayoutPanel>().FirstOrDefault();if(labels.Count<2||filters==null)return;int available=Math.Max(200,header.ClientSize.Width-header.Padding.Horizontal-filters.Padding.Horizontal-8);foreach(var box in filters.Controls.OfType<ComboBox>()){int width=TextRenderer.MeasureText(box.Text,box.Font).Width+42;box.Width=Math.Max(120,Math.Min(300,width));}int rowsHeight=0,rowWidth=0,rowHeight=0;foreach(Control c in filters.Controls){int width=c.Width+c.Margin.Horizontal;int height=Math.Max(c.Height,c.Font.Height+12)+c.Margin.Vertical;if(rowWidth>0&&rowWidth+width>available){rowsHeight+=rowHeight;rowHeight=0;rowWidth=0;}rowWidth+=width;rowHeight=Math.Max(rowHeight,height);}filters.Height=Math.Max(66,rowsHeight+rowHeight+filters.Padding.Vertical);labels[0].Location=new Point(18,12);labels[1].Location=new Point(20,labels[0].Bottom+5);bool enlarged=search.Font.Height>20;if(enlarged){int y=labels[1].Bottom+8;search.Location=new Point(20,y);search.Width=Math.Max(180,Math.Min(350,available/2-12));scope.Width=Math.Max(180,Math.Min(320,available-search.Width-12));scope.Location=new Point(search.Right+12,y);header.Height=Math.Max(132,y+Math.Max(search.Height,scope.Height)+filters.Height+20);}else{scope.Width=170;scope.Location=new Point(header.ClientSize.Width-190,22);search.Width=210;search.Location=new Point(scope.Left-220,22);header.Height=Math.Max(132,labels[1].Bottom+filters.Height+12);}}finally{fittingHeader=false;}}
