.ConsoleLabel+"]":""),e==null?"Not assigned":e.Name,path,size,string.IsNullOrWhiteSpace(g.LastLaunched)?"Never":g.LastLaunched};for(int i=0;i<values.Length;i++)if(row.SubItems[i].Text!=values[i])row.SubItems[i].Text=values[i];row.ToolTipText=size=="Missing"?"Missing game file. Use Library tools → Repair game paths.":e==null?"Assign an emulator in Game actions → Edit game.":"Enter or double-click to launch. Game actions contains editing and saves.";row.Selected=selected.Contains(g.Id);}
    if(orderChanged&&list.Count>0){var positions=list.Select((g,i)=>new{g.Id,Index=i}).ToDictionary(x=>x.Id,x=>x.Index);games.ListViewItemSorter=new RowOrder(positions);games.Sort();games.ListViewItemSorter=null;}ApplyArtworkView();if(selected.Count==0&&polishReady){var n=UserTools.Ensure(library).Navigation;if(n!=null&&!string.IsNullOrWhiteSpace(n.SelectedId)&&reusableRows.ContainsKey(n.SelectedId))reusableRows[n.SelectedId].Selected=true;if(top==null&&n!=null)top=n.TopId;}if(top!=null&&reusableRows.ContainsKey(top)){if(games.View==View.Details)games.TopItem=reusableRows[top];else reusableRows[top].EnsureVisible();}}
