  void ApplyLazyArtwork(){UpdateDetailPane();games.TileSize=new Size(Math.Max(130,library.Experience.ArtworkSize+24),library.Experience.ArtworkSize+(library.Cosmetics!=null&&library.Cosmetics.LibrarySpacing=="Compact"?32:55));games.View=artworkView?View.LargeIcon:View.Details;ApplyHubSpacing();if(!artworkView)return;int size=Math.Max(64,Math.Min(192,library.Experience.ArtworkSize));string style=Json.Serialize(CosmeticRuntime.Current)+"|"+FishBowlPalette.ThemeSurface.ToArgb()+"|"+FishBowlPalette.ThemeInk.ToArgb()+"|"+FishBowlPalette.IconAccent.ToArgb();if(size!=artSize||style!=artStyle||coverImages.Images.Count==0){thumbnailSlots.Clear();slotOwners.Clear();nextSlot=1;coverImages.Images.Clear();coverImages.ImageSize=new Size(size,size);var imageHandle=coverImages.Handle;using(var placeholder=MakeThumbnail(null,"?",size))coverImages.Images.Add(placeholder);artSize=size;artStyle=style;foreach(ListViewItem item in games.Items)item.ImageIndex=0;}LoadVisibleArtwork();}
  public static Bitmap MakeThumbnail(string path,string title,int size){var bitmap=new Bitmap(size,size);using(var graphics=Graphics.FromImage(bitmap)){graphics.Clear(FishBowlPalette.ThemeSurface);bool loaded=false;try{if(!string.IsNullOrWhiteSpace(path)&&File.Exists(path)){using(var image=Image.FromFile(path)){if(image.Width<12000&&image.Height<12000){graphics.DrawImage(image,new Rectangle(4,4,size-8,size-8));loaded=true;}}}}catch{}if(!loaded)using(var font=new Font("Segoe UI",Math.Max(8,size/3),FontStyle.Bold))FishBowlText.DrawText(graphics,string.IsNullOrWhiteSpace(title)?"?":title.Substring(0,1).ToUpperInvariant(),font,new Rectangle(0,0,size,size),FishBowlPalette.ThemeInk,TextFormatFlags.HorizontalCenter|TextFormatFlags.VerticalCenter);CosmeticRuntime.DecorateArtwork(bitmap);}return bitmap;}
  void LoadVisibleArtwork(){if(!polishReady||!artworkView||thumbnailBusy||!games.Visible||!games.IsHandleCreated||games.Items.Count==0)return;var visible=new HashSet<ListViewItem>();for(int y=8;y<games.ClientSize.Height;y+=32)for(int x=8;x<games.ClientSize.Width;x+=32){var item=games.GetItemAt(x,y);if(item!=null)visible.Add(item);}foreach(var item in visible){var g=item.Tag as GameEntry;if(g==null)continue;long stamp=0;try{if(File.Exists(g.ArtworkPath))stamp=File.GetLastWriteTimeUtc(g.ArtworkPath).Ticks;}catch{}string key=(g.ArtworkPath??"")+"|"+g.Title+"|"+g.ConsoleLabel+"|"+stamp+"|"+artSize+"|"+artStyle;int slot;if(thumbnailSlots.TryGetValue(key,out slot)){item.ImageIndex=slot;if(!slotOwners.ContainsKey(slot))slotOwners[slot]=new HashSet<ListViewItem>();slotOwners[slot].Add(item);continue;}thumbnailBusy=true;string path=g.ArtworkPath,title=g.Title,platform=g.ConsoleLabel;bool badge=library.Cosmetics!=null&&library.Cosmetics.PlatformLabels;int size=artSize;string style=artStyle;Task.Factory.StartNew(()=>Hub.PlatformThumbnail(path,title,platform,size,badge)).ContinueWith(task=>{if(task.IsFaulted){thumbnailBusy=false;return;}var bitmap=task.Result;if(IsDisposed||Disposing||!IsHandleCreated){bitmap.Dispose();return;}try{BeginInvoke((Action)(()=>{try{if(IsDisposed||Disposing||artSize!=size||artStyle!=style)return;int use=nextSlot++;if(use>=128){nextSlot=2;use=1;}if(use<coverImages.Images.Count){foreach(var old in thumbnailSlots.Where(k=>k.Value==use).Select(k=>k.Key).ToArray())thumbnailSlots.Remove(old);HashSet<ListViewItem> previous;if(slotOwners.TryGetValue(use,out previous))foreach(var old in previous)if(old.ListView==games)old.ImageIndex=0;coverImages.Images[use]=bitmap;}else coverImages.Images.Add(bitmap);thumbnailSlots[key]=use;slotOwners[use]=new HashSet<ListViewItem>{item};if(item.ListView==games)item.ImageIndex=use;}finally{bitmap.Dispose();thumbnailBusy=false;}}));}catch(InvalidOperationException){bitmap.Dispose();thumbnailBusy=false;}});break;}}
